// 魔晶石装填器 · 剑内置物品宏
try {
  // 仅「装填」行动触发；挥砍等其它行动忽略
  const wf = (typeof workflow !== "undefined" && workflow) ? workflow : null;
  if (wf && wf.activity && !(wf.activity.name || "").includes("装填")) return;

  const blade = item;
  const WID = blade.id;
  const SLOTS = 3;
  const maxTok = Number(blade.system.uses?.max) || 1;
  const editAvail = (blade.system.uses?.spent ?? 0) < maxTok;

  const slotted = {};
  for (const it of actor.items) {
    const m = it.getFlag("world", "materiaSlot");
    if (m && m.weapon === WID) slotted[m.slot] = it;
  }
  const templates = game.items.filter(i => i.getFlag("world", "materiaStoneId"));
  const tplOpts = templates.map(t => `<option value="${t.id}">${t.name}（${t.system.price?.value ?? 0} GP）</option>`).join("");
  const gp = actor.system.currency?.gp ?? 0;

  let content = `<p style="margin:.3em 0">为 <b>${blade.name}</b> 管理魔晶石（3 槽，可重复装同一种）。当前金币：<b>${gp} GP</b>。</p>`;
  content += editAvail
    ? `<p style="font-size:.85em;opacity:.8">本次长休可装填：每装 1 颗按该魔晶石的标价扣费；替换或清空会销毁原石（不退回）。</p>`
    : `<p style="color:#a55;font-size:.85em">本次长休的装填额度已用完——下次长休后可再改。当前为只读查看。</p>`;
  for (let n = 1; n <= SLOTS; n++) {
    const cur = slotted[n] ? `<b>${slotted[n].name}</b>` : `<i>空</i>`;
    content += `<div style="margin:.35em 0;padding:.35em;border:1px solid #0003;border-radius:6px"><div>晶槽 ${n} — 当前：${cur}</div>`;
    if (editAvail) {
      content += `<select name="slot${n}" style="width:100%;margin-top:.25em"><option value="">— 保持当前 —</option>`
        + (slotted[n] ? `<option value="__clear__">— 清空本槽（销毁原石）—</option>` : ``)
        + tplOpts + `</select>`;
    }
    content += `</div>`;
  }
  if (editAvail && !templates.length)
    content += `<p style="color:#a55">没找到魔晶石模板，请先把 8 颗石头导入「物品」目录。</p>`;

  async function applyLoad(event, button, dialog) {
    const root = dialog.element;
    let changed = false;
    let gpLeft = actor.system.currency?.gp ?? 0;
    const dc = actor.system.attributes?.spelldc ?? 13;
    for (let n = 1; n <= SLOTS; n++) {
      const pick = root.querySelector(`[name="slot${n}"]`)?.value;
      if (!pick) continue;
      if (slotted[n]) { try { await slotted[n].delete(); } catch (_) {} }
      if (pick === "__clear__") { changed = true; continue; }
      const tpl = templates.find(t => t.id === pick);
      if (!tpl) continue;
      const cost = tpl.system.price?.value ?? 0;
      if (gpLeft < cost) { ui.notifications.warn(`金币不足（需 ${cost} GP），晶槽 ${n} 未装填。`); continue; }
      gpLeft -= cost;
      const data = tpl.toObject();
      delete data._id;
      data.name = `〔晶槽${n}〕` + tpl.name;
      foundry.utils.setProperty(data, "flags.world.materiaSlot", { weapon: WID, slot: n });
      for (const ef of (data.effects || [])) {
        for (const ch of (ef.changes || [])) {
          if (ch.key === "flags.midi-qol.OverTime")
            ch.value = String(ch.value).replace(/saveDC=\d+/, `saveDC=${dc}`);
        }
      }
      await actor.createEmbeddedDocuments("Item", [data]);
      changed = true;
    }
    if (changed) {
      await actor.update({ "system.currency.gp": gpLeft });
      await blade.update({ "system.uses.spent": maxTok });
      ui.notifications.info(`${blade.name}：装填完成，剩余 ${gpLeft} GP。`);
    }
  }

  const buttons = editAvail
    ? [{ action: "save", icon: "fa-solid fa-gem", label: "确认装填", default: true, callback: applyLoad },
       { action: "cancel", icon: "fa-solid fa-xmark", label: "取消" }]
    : [{ action: "ok", icon: "fa-solid fa-eye", label: "关闭", default: true }];

  new foundry.applications.api.DialogV2({ window: { title: `魔晶石装填器 · ${blade.name}` }, content, buttons }).render(true);
} catch (err) { console.error("MateriaLoader |", err); }

